function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[0-9]+$/.test(s)) return 's may contain only digits.';
  if (!Number.isInteger(k) || k < 2 || k > 100) return 'k is an integer from 2 to 100.';
  return null;
}

