function digitSum(s, k) {
  while (s.length > k) {
    let next = '';
    for (let start = 0; start < s.length; start += k) {
      const end = Math.min(start + k, s.length);
      let groupSum = 0;
      for (let i = start; i < end; i++) {
        groupSum += Number(s[i]);
      }
      next += String(groupSum);
    }
    s = next;
  }
  return s;
}

brute:
function digitSum(s, k) {
  if (s.length <= k) return s;
  const groups = s.match(new RegExp(`\\d{1,${k}}`, 'g'));
  const sums = groups.map(group => group.split('').reduce((total, ch) => total + (ch.charCodeAt(0) - 48), 0));
  return digitSum(sums.join(''), k);
}

