function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 15);
  const k = size === 'large' ? 2 + Math.floor(rand() * (rand() < 0.7 ? 8 : 99)) : 2 + Math.floor(rand() * 5);
  // Some strings lean towards nines or zeros so that sums of every width appear.
  const style = rand();
  let s = '';
  for (let i = 0; i < n; i++) {
    if (style < 0.2) s += rand() < 0.8 ? '9' : String(Math.floor(rand() * 10));
    else if (style < 0.35) s += rand() < 0.8 ? '0' : String(Math.floor(rand() * 10));
    else s += String(Math.floor(rand() * 10));
  }
  return [s, k];
}
